hooks.command:
n=$(grep -LE "^> ✅" days/*.md 2>/dev/null | sed "s|days/||;s|\.md||" | sort | tr "
" " "); p=$(grep -lE "^> ✅.*初步確認" days/*.md 2>/dev/null | sed "s|days/||;s|\.md||" | sort | tr "
" " "); if [ -n "$n" ] || [ -n "$p" ]; then printf '{"systemMessage":"commit 前請審核每日行程確認狀態：尚未查證 → %s｜僅初步確認 → %s"}
' "${n:-無}" "${p:-無}"; else printf '{"systemMessage":"days/ 內每日行程皆已完整確認"}
'; fi
